const LABEL_PRESETS={
  '50x30':{width:50,height:30,label:'50 × 30 мм'},
  '50x25':{width:50,height:25,label:'50 × 25 мм'},
  '40x30':{width:40,height:30,label:'40 × 30 мм'},
  '58x40':{width:58,height:40,label:'58 × 40 мм'},
  '70x40':{width:70,height:40,label:'70 × 40 мм'}
};
function loadLabelSettings(){try{const raw=localStorage.getItem('x86stock_label_settings');if(raw){const v=JSON.parse(raw);state.labelSettings={...state.labelSettings,...v}}}catch(e){}syncLabelSettingsUI()}
function saveLabelSettings(){try{localStorage.setItem('x86stock_label_settings',JSON.stringify(state.labelSettings))}catch(e){}}
function syncLabelSettingsUI(){const size=$('#label-size'),mode=$('#label-text-mode'),dpi=$('#label-dpi'),box=$('#label-custom-size');if(!size||!mode)return;size.value=state.labelSettings.size||'50x30';mode.value=state.labelSettings.textMode||'auto';if(dpi)dpi.value=String(Number(state.labelSettings.dpi||203));$('#label-width').value=Number(state.labelSettings.width||50);$('#label-height').value=Number(state.labelSettings.height||30);box.classList.toggle('hidden',size.value!=='custom')}
function readLabelSettingsUI(){const size=$('#label-size')?.value||state.labelSettings.size||'50x30';const preset=LABEL_PRESETS[size];state.labelSettings.size=size;state.labelSettings.textMode=$('#label-text-mode')?.value||'auto';state.labelSettings.dpi=Number($('#label-dpi')?.value||state.labelSettings.dpi||203)===300?300:203;if(preset){state.labelSettings.width=preset.width;state.labelSettings.height=preset.height}else{state.labelSettings.width=Math.max(25,Math.min(120,Number($('#label-width')?.value||50)));state.labelSettings.height=Math.max(15,Math.min(100,Number($('#label-height')?.value||30)))}saveLabelSettings();syncLabelSettingsUI()}
function labelSettingsSummary(){const st=state.labelSettings,p=LABEL_PRESETS[st.size];const size=p?p.label:`${st.width} × ${st.height} мм`;const modes={auto:'модель + параметры',full:'полное название',model:'модель ocStore'};return `PDF: ${size} · ${Number(st.dpi||203)} dpi · ${modes[st.textMode]||modes.auto}`}
