function decodeLabelText(value){
  const s=String(value??'');
  if(!s.includes('&'))return s;
  const el=document.createElement('textarea');
  el.innerHTML=s;
  return el.value;
}
function normalizeLabelSource(value){return decodeLabelText(value).replace(/\s+/g,' ').trim()}
function stripLabelLeadNoise(value){
  let rest=String(value||'').trim(),prev='';
  // В JS \b не является надёжной границей для кириллицы, поэтому используем (?=\\s|$).
  while(rest!==prev){
    prev=rest;
    rest=rest
      .replace(/^[-–—,:;|/]+\s*/,'')
      .replace(/^\((?:вентилятор|кулер|батарея|аккумулятор|акб|адаптер|зарядка|дисплей|экран|матрица)\)\s*/i,'')
      .replace(/^для\s+(?:ноутбука|ноутбуков|смартфона|смартфонов|телефона|телефонов|телевизора|телевизоров|пк|компьютера|компьютеров)(?=\s|$)\s*/i,'')
      .replace(/^(?:ноутбука|ноутбуков|смартфона|смартфонов|телефона|телефонов|телевизора|телевизоров)(?=\s|$)\s*/i,'')
      .replace(/^для(?=\s|$)\s*/i,'')
      .trim();
  }
  return rest;
}
const LABEL_TYPE_RULES=[
  {re:/^клавиатура(?=\s|$)/i,label:()=> 'Клавиатура'},
  {re:/^(?:аккумулятор|акб|батарея)(?=\s|$)/i,label:()=> 'АКБ'},
  {re:/^(?:кулер|вентилятор)(?:\s+(cpu|gpu))?(?=\s|$)/i,label:m=> 'Кулер'+(m[1]?' '+m[1].toUpperCase():'')},
  {re:/^(?:матрица|дисплей|экран)(?=\s|$)/i,label:()=> 'Матрица'},
  {re:/^(?:блок\s+питания|зарядное\s+устройство|адаптер\s+питания|зарядка)(?=\s|$)/i,label:()=> 'Блок питания'},
  {re:/^шлейф(?=\s|$)/i,label:()=> 'Шлейф'},
  {re:/^раз[ъь]ем(?=\s|$)/i,label:()=> 'Разъём'},
  {re:/^петл[яи](?=\s|$)/i,label:()=> 'Петля'},
  {re:/^корпус(?=\s|$)/i,label:()=> 'Корпус'}
];
function splitLabelType(name){
  for(const r of LABEL_TYPE_RULES){
    const m=name.match(r.re);
    if(m)return {match:m[0],canonical:r.label(m)};
  }
  return null;
}
function compactLabelTitle(p){
  const name=normalizeLabelSource(p?.name||'');
  if(!name)return normalizeLabelSource(p?.model||'');
  const type=splitLabelType(name);
  if(type){
    const rest=stripLabelLeadNoise(name.slice(type.match.length));
    return (type.canonical+(rest?' '+rest:'')).replace(/\s+/g,' ').trim();
  }
  const cleaned=stripLabelLeadNoise(name);
  const service=cleaned.replace(/^ремонт\s+(?:смартфонов|телефонов|ноутбуков|телевизоров)\s*/i,'').trim();
  return service||cleaned||name;
}
function cleanFullLabelTitle(p){
  const name=normalizeLabelSource(p?.name||'');
  if(!name)return normalizeLabelSource(p?.model||'');
  const type=splitLabelType(name);
  if(type){
    const originalPrefix=name.slice(0,type.match.length).trim();
    const rest=stripLabelLeadNoise(name.slice(type.match.length));
    return (originalPrefix+(rest?' '+rest:'')).replace(/\s+/g,' ').trim();
  }
  return stripLabelLeadNoise(name)||name;
}
function labelTitle(p,mode=state.labelSettings.textMode){if(mode==='full')return cleanFullLabelTitle(p);if(mode==='model'){const m=normalizeLabelSource(p?.model||'');if(m&&/[A-Za-zА-Яа-я]/.test(m))return m;return compactLabelTitle(p)}return compactLabelTitle(p)}

