function addLabelProduct(p,count=1){if(!p)return;const found=state.labelQueue.find(x=>x.product.product_id==p.product_id);if(found)found.count+=Math.max(1,Number(count||1));else state.labelQueue.push({product:p,count:Math.max(1,Number(count||1))});renderLabelQueue()}
function renderLabelQueue(){const box=$('#label-queue');if(!box)return;const total=state.labelQueue.reduce((s,x)=>s+Number(x.count||0),0);$('#label-total').textContent=total+' шт.';if(!state.labelQueue.length){box.innerHTML='<div class="empty-state">Добавьте товары через поиск или сканер.</div>';return}box.innerHTML=`<div class="pretty-list label-queue-list">${state.labelQueue.map((x,k)=>`<div class="label-queue-row pretty-list-card tone-violet"><div class="pretty-list-main"><div class="pretty-list-title">${esc(x.product.name)}</div><div class="label-preview-text">На этикетке: ${esc(labelTitle(x.product))}</div><div class="pretty-list-meta"><span>${esc(x.product.model)}</span><span>${money(x.product.price)}</span></div></div><input data-label-qty="${k}" type="number" min="1" max="999" value="${x.count}"><button class="icon-remove" data-label-del="${k}" aria-label="Удалить">×</button></div>`).join('')}</div>`;$$('[data-label-qty]').forEach(i=>i.onchange=()=>{state.labelQueue[i.dataset.labelQty].count=Math.max(1,Number(i.value||1));renderLabelQueue()});$$('[data-label-del]').forEach(b=>b.onclick=()=>{state.labelQueue.splice(Number(b.dataset.labelDel),1);renderLabelQueue()})}
$('#label-clear').onclick=()=>{state.labelQueue=[];renderLabelQueue()};
