const CODE128_PATTERNS=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312113','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];
function code128Values(value){let code=String(value||'X86').split('').filter(ch=>{const o=ch.charCodeAt(0);return o>=32&&o<=126}).join('');if(!code)code='X86';const vals=[104];let checksum=104,pos=1;for(const ch of code){const v=ch.charCodeAt(0)-32;vals.push(v);checksum+=v*pos;pos++}vals.push(checksum%103,106);return {code,vals}}
function drawCode128(ctx,value,x,y,w,h){const d=code128Values(value),quiet=5;let modules=quiet*2;for(const v of d.vals)for(const ch of CODE128_PATTERNS[v])modules+=Number(ch);let cursor=quiet;ctx.fillStyle='#000';for(const v of d.vals){let bar=true;for(const ch of CODE128_PATTERNS[v]){const mw=Number(ch),x1=Math.round(x+(cursor/modules)*w),x2=Math.round(x+((cursor+mw)/modules)*w);if(bar)ctx.fillRect(x1,Math.round(y),Math.max(1,x2-x1),Math.max(1,Math.round(h)));cursor+=mw;bar=!bar}}return d.code}
function canvasWrappedLines(ctx,text,maxWidth){const words=String(text||'').replace(/\s+/g,' ').trim().split(' ').filter(Boolean),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width<=maxWidth){line=test;continue}if(line){lines.push(line);line=''}if(ctx.measureText(word).width<=maxWidth){line=word;continue}let part='';for(const ch of word){const t=part+ch;if(ctx.measureText(t).width>maxWidth&&part){lines.push(part);part=ch}else part=t}line=part}if(line)lines.push(line);return lines}
function fitCanvasTitle(ctx,text,maxWidth,maxHeight,startPt,minPt,dpi){for(let pt=startPt;pt>=minPt;pt-=0.25){const px=pt*dpi/72;ctx.font=`800 ${px}px Arial, sans-serif`;const lines=canvasWrappedLines(ctx,text,maxWidth),lineH=px*1.03;if(lines.length*lineH<=maxHeight)return {pt,px,lineH,lines}}const px=minPt*dpi/72;ctx.font=`800 ${px}px Arial, sans-serif`;return {pt:minPt,px,lineH:px*1.02,lines:canvasWrappedLines(ctx,text,maxWidth)}}
function drawFittedSingleLine(ctx,text,x,y,maxWidth,pt,dpi,align='left'){let p=pt;const val=String(text||'');while(p>4.5){ctx.font=`700 ${p*dpi/72}px Arial, sans-serif`;if(ctx.measureText(val).width<=maxWidth)break;p-=0.25}ctx.textAlign=align;ctx.textBaseline='top';ctx.fillText(val,x,y,maxWidth)}
function renderLabelCanvas(product,widthMm,heightMm,mode,dpiSetting){const dpi=dpiSetting===300?300:203.2,ppm=dpi/25.4,W=Math.max(1,Math.round(widthMm*ppm)),H=Math.max(1,Math.round(heightMm*ppm)),cv=document.createElement('canvas');cv.width=W;cv.height=H;const ctx=cv.getContext('2d',{alpha:false});ctx.imageSmoothingEnabled=false;ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#000';const mm=v=>v*ppm,pad=Math.max(0.9,Math.min(1.5,widthMm/40)),small=heightMm<=25||widthMm<=40,topPt=small?6.4:7.2,metaPt=small?4.8:5.5;ctx.textBaseline='top';ctx.textAlign='left';ctx.font=`800 ${topPt*dpi/72}px Arial, sans-serif`;ctx.fillText('X86.kz',mm(pad),mm(pad));const model=normalizeLabelSource(product.model||'');if(model)drawFittedSingleLine(ctx,model,W-mm(pad),mm(pad),W*0.42,metaPt,dpi,'right');const title=labelTitle(product,mode),titleY=mm(pad+3.5),bottomH=Math.max(8.2,Math.min(11.5,heightMm*0.34)),bottomY=H-mm(pad+bottomH),titleMaxH=Math.max(mm(4.5),bottomY-titleY-mm(0.5)),titleMaxW=W-mm(pad*2),titleStartPt=mode==='full'?(small?7.1:8.1):(small?7.8:9.2),fit=fitCanvasTitle(ctx,title,titleMaxW,titleMaxH,titleStartPt,5.2,dpi);ctx.font=`800 ${fit.px}px Arial, sans-serif`;ctx.textAlign='left';ctx.textBaseline='top';let ty=titleY;for(const line of fit.lines){if(ty+fit.lineH>titleY+titleMaxH+1)break;ctx.fillText(line,mm(pad),ty,titleMaxW);ty+=fit.lineH}const barcodeX=mm(pad+0.5),barcodeW=Math.min(mm(widthMm*0.62),W-mm(pad*2)-mm(widthMm*0.26)),barsH=mm(Math.max(5.5,Math.min(8.2,bottomH-2.3))),barsY=bottomY+mm(0.1),barcode=String(product.barcode||('X86-'+product.product_id));drawCode128(ctx,barcode,barcodeX,barsY,barcodeW,barsH);ctx.font=`500 ${Math.max(4.4,small?4.5:5.1)*dpi/72}px Arial, sans-serif`;ctx.textAlign='center';ctx.textBaseline='top';ctx.fillText(barcode,barcodeX+barcodeW/2,barsY+barsH+mm(0.15),barcodeW);const price=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(product.price||0)).replace(/[\u00A0\u202F]/g,' ')+' ₸',priceX=W-mm(pad),priceY=bottomY+mm(Math.max(1.5,(bottomH-4)/2)),pricePt=small?8.8:Math.min(12.5,9.5+Math.max(0,(widthMm-40)/12));drawFittedSingleLine(ctx,price,priceX,priceY,W-barcodeX-barcodeW-mm(1.3),pricePt,dpi,'right');return cv}
function canvasToMonoBitmap(canvas){const ctx=canvas.getContext('2d'),img=ctx.getImageData(0,0,canvas.width,canvas.height).data,stride=Math.ceil(canvas.width/8),out=new Uint8Array(stride*canvas.height);for(let y=0;y<canvas.height;y++){const row=y*stride;for(let x=0;x<canvas.width;x++){const i=(y*canvas.width+x)*4,gray=(img[i]*299+img[i+1]*587+img[i+2]*114)/1000;if(gray>=185)out[row+(x>>3)]|=1<<(7-(x&7))}}return out}
function buildMonoImagePdf(pages,widthMm,heightMm){const enc=new TextEncoder(),chunks=[];let total=0;const push=v=>{const u=typeof v==='string'?enc.encode(v):v;chunks.push(u);total+=u.byteLength};push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');const count=pages.length,maxId=2+count*3,objects=new Array(maxId+1),kids=[];objects[1]={dict:'<< /Type /Catalog /Pages 2 0 R >>'};for(let i=0;i<count;i++)kids.push(`${3+i*3} 0 R`);objects[2]={dict:`<< /Type /Pages /Count ${count} /Kids [ ${kids.join(' ')} ] >>`};const W=(widthMm*72/25.4).toFixed(4),H=(heightMm*72/25.4).toFixed(4);for(let i=0;i<count;i++){const pageId=3+i*3,imgId=pageId+1,contentId=pageId+2,p=pages[i],content=enc.encode(`q\n${W} 0 0 ${H} 0 0 cm\n/Im0 Do\nQ\n`);objects[pageId]={dict:`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /CropBox [0 0 ${W} ${H}] /Resources << /XObject << /Im0 ${imgId} 0 R >> >> /Contents ${contentId} 0 R >>`};objects[imgId]={dict:`<< /Type /XObject /Subtype /Image /Width ${p.width} /Height ${p.height} /ColorSpace /DeviceGray /BitsPerComponent 1 /Length ${p.data.byteLength} >>`,stream:p.data};objects[contentId]={dict:`<< /Length ${content.byteLength} >>`,stream:content}}const offsets=new Array(maxId+1).fill(0);for(let id=1;id<=maxId;id++){offsets[id]=total;const o=objects[id];push(`${id} 0 obj\n${o.dict}\n`);if(o.stream){push('stream\n');push(o.stream);push('\nendstream\n')}push('endobj\n')}const xref=total;push(`xref\n0 ${maxId+1}\n0000000000 65535 f \n`);for(let id=1;id<=maxId;id++)push(String(offsets[id]).padStart(10,'0')+' 00000 n \n');push(`trailer\n<< /Size ${maxId+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`);return new Blob(chunks,{type:'application/pdf'})}
function labelPdfFilename(width,height){const d=new Date(),z=n=>String(n).padStart(2,'0');return `x86-labels-${width}x${height}-${d.getFullYear()}${z(d.getMonth()+1)}${z(d.getDate())}-${z(d.getHours())}${z(d.getMinutes())}.pdf`}
async function printLabelItems(items){readLabelSettingsUI();const clean=items.filter(x=>x&&x.product&&Number(x.count)>0);if(!clean.length)return toast('Нет этикеток для PDF');const width=Number(state.labelSettings.width||50),height=Number(state.labelSettings.height||30),mode=state.labelSettings.textMode||'auto',dpi=Number(state.labelSettings.dpi||203)===300?300:203,totalLabels=clean.reduce((s,x)=>s+Math.min(999,Math.max(1,Number(x.count||1))),0);if(totalLabels>400&&!confirm(`Будет создано ${totalLabels} страниц PDF. Это может занять некоторое время. Продолжить?`))return;const btn=$('#label-print-all'),oldText=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='Создаю PDF…'}toast(`Создаю PDF: ${totalLabels} этикеток…`);try{const pages=[];let done=0;for(const x of clean){const count=Math.min(999,Math.max(1,Number(x.count||1)));for(let n=0;n<count;n++){const cv=renderLabelCanvas(x.product,width,height,mode,dpi);pages.push({width:cv.width,height:cv.height,data:canvasToMonoBitmap(cv)});done++;if(done%15===0){if(btn)btn.textContent=`PDF ${done}/${totalLabels}`;await new Promise(r=>setTimeout(r,0))}}}const blob=buildMonoImagePdf(pages,width,height),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=labelPdfFilename(width,height);document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast(`PDF готов: ${totalLabels} шт. · ${width}×${height} мм`)}catch(e){console.error(e);toast('Ошибка PDF: '+e.message)}finally{if(btn){btn.disabled=false;btn.textContent=oldText||'Скачать PDF'}}}


function renderStale(rows){if(!rows.length)return '<div class="empty-state compact">Нет залежавшихся товаров.</div>';return `<div class="pretty-list">${rows.map(r=>`<div class="pretty-list-card clickable tone-orange" data-open-product="${Number(r.product_id||0)}"><div class="pretty-list-main"><div class="pretty-list-title">${esc(r.name)}</div><div class="pretty-list-meta"><span>${esc(r.model)}</span><span>${Number(r.quantity||0)} шт.</span><span>Продажа: ${r.last_sale||'не было'}</span></div></div><div class="pretty-list-side"><b>${money(r.frozen)}</b><small>заморожено</small></div><div class="pretty-arrow">›</div></div>`).join('')}</div>`}
function renderTop(rows){if(!rows.length)return '<div class="empty-state compact">Пока нет данных по прибыли.</div>';return `<div class="pretty-list">${rows.map((r,i)=>`<div class="pretty-list-card clickable tone-green" data-open-product="${Number(r.product_id||0)}"><div class="rank-chip">${i+1}</div><div class="pretty-list-main"><div class="pretty-list-title">${esc(r.name)}</div><div class="pretty-list-meta"><span>${Number(r.qty||0)} шт.</span><span>Выручка ${money(r.revenue)}</span></div></div><div class="pretty-list-side"><b>${money(r.profit)}</b><small>прибыль</small></div><div class="pretty-arrow">›</div></div>`).join('')}</div>`}
function renderInventoryCategories(rows){if(!rows||!rows.length)return '<div class="empty-state compact">Нет данных по категориям.</div>';const max=Math.max(...rows.map(r=>Number(r.cost_value||0)),1);return `<div class="pretty-list category-value-list">${rows.map((r,i)=>{const val=Number(r.cost_value||0),pct=Math.max(2,Math.round(val/max*100));return `<div class="pretty-list-card category-value-card tone-violet"><div class="category-rank">${i+1}</div><div class="pretty-list-main"><div class="pretty-list-title">${esc(r.name||'Без категории')}</div><div class="pretty-list-meta"><span>${Number(r.positions||0)} поз.</span><span>${Number(r.units||0)} шт.</span></div><div class="category-bar"><i style="width:${pct}%"></i></div></div><div class="pretty-list-side"><b>${money(val)}</b><small>себестоимость</small></div></div>`}).join('')}</div>`}
async function loadAnalytics(){try{const j=await api('analytics');state.analyticsData=j;const d=j.dashboard,invNote=`Учтено: ${Number(d.inventory_costed_products||0)} поз. · ${Number(d.inventory_costed_units||0)} шт.`;$('#analytics-cards').innerHTML=cards([['Стоимость склада',money(d.inventory_value),'tone-violet',invNote],['Заморожено 90+',money(d.frozen_value),Number(d.frozen_value)>0?'tone-red':'tone-green'],['Низкий остаток',d.low_stock,Number(d.low_stock)>0?'tone-amber':'tone-green'],['Прибыль сегодня',money(d.today_profit),'tone-green']]);$('#inventory-category-list').innerHTML=renderInventoryCategories(j.inventory_categories||[]);$('#analytics-recs').innerHTML=listRecs(j.recommendations.slice(0,12));$('#stale-list').innerHTML=renderStale(j.stale);$('#top-list').innerHTML=renderTop(j.top);bindOpenProducts($('.page[data-page="analytics"]'))}catch(e){toast(e.message)}}
function isUrgentProcurement(r){const q=Number(r.quantity||0),cover=Number(r.days_cover||999),lead=Number(r.lead_time_days||0);return q<=0||cover<=7||(lead>0&&cover<=lead)}
function renderProcurement(rows){const filtered=state.procurementFilter==='urgent'?rows.filter(isUrgentProcurement):rows;$('#procurement-count').textContent=filtered.length+' поз.';if(!filtered.length)return '<div class="empty-state">В этой группе сейчас ничего закупать не нужно.</div>';return `<div class="pretty-list procurement-list">${filtered.map((r,i)=>{const cost=Number(r.order_cost||0),cover=Number(r.days_cover||0),lead=Number(r.lead_time_days||0);return `<div class="pretty-list-card procurement-card clickable ${urgencyClass(r)}" data-open-product="${Number(r.product_id||0)}"><div class="procurement-index">${i+1}</div><div class="pretty-list-main"><div class="pretty-list-title">${esc(r.name||r.model)}</div><div class="pretty-list-meta"><span>${esc(r.model||'')}</span><span>Остаток ${Number(r.quantity||0)}</span><span>Продано 30д: ${Number(r.sold30||0)}</span></div><div class="procurement-details"><span>Запас ≈ <b>${cover} дн.</b></span><span>Поставка <b>${lead} дн.</b></span>${Number(r.cost_price||0)>0?`<span>Закуп <b>${money(r.cost_price)}</b></span>`:''}</div></div><div class="procurement-order"><small>Заказать</small><b>+${Number(r.order_qty||0)} шт.</b>${cost>0?`<span>≈ ${money(cost)}</span>`:'<span>без суммы</span>'}</div><div class="pretty-arrow">›</div></div>`}).join('')}</div>`}
async function loadProcurement(){try{const j=await api('analytics');state.analyticsData=j;const rows=j.recommendations||[],positions=rows.length,units=rows.reduce((a,r)=>a+Number(r.order_qty||0),0),budget=rows.reduce((a,r)=>a+Number(r.order_cost||0),0),urgent=rows.filter(isUrgentProcurement).length,missingCost=rows.filter(r=>Number(r.order_qty||0)>0&&Number(r.cost_price||0)<=0).length;$('#procurement-cards').innerHTML=cards([['Позиций',positions,'tone-blue'],['Заказать шт.',units,'tone-violet'],['Срочно',urgent,urgent>0?'tone-red':'tone-green'],['Бюджет',money(budget),'tone-amber',missingCost?`Без себестоимости: ${missingCost} поз.`:'По текущей себестоимости']]);$('#procurement-list').innerHTML=renderProcurement(rows);bindOpenProducts($('#procurement-list'))}catch(e){toast(e.message)}}
$$('[data-proc-filter]').forEach(b=>b.onclick=()=>{$$('[data-proc-filter]').forEach(x=>x.classList.toggle('active',x===b));state.procurementFilter=b.dataset.procFilter||'all';const rows=state.analyticsData?.recommendations||[];$('#procurement-list').innerHTML=renderProcurement(rows);bindOpenProducts($('#procurement-list'))});
$$('.quick-ai button').forEach(b=>b.onclick=()=>{$('#ai-question').value=b.textContent;$('#ai-send').click()});
function aiValue(field,v){if(['price','partner_price','cost_price'].includes(field))return money(v);if(field==='quantity'||field==='min_stock')return Number(v)+' шт.';if(field==='lead_time_days')return Number(v)+' дн.';return String(v??'—')}
function renderAiPlan(plan){state.aiPlan=plan;const box=$('#ai-plan');if(!plan||!plan.items?.length){box.classList.add('hidden');box.innerHTML='';return}box.classList.remove('hidden');box.innerHTML=`<div class="ai-plan-head"><div><b>План изменений</b><span>${esc(plan.summary||'')}</span></div><span class="badge">${plan.count} поз.</span></div><div class="ai-plan-warning">Проверьте список. Пока вы не нажали «Подтвердить и применить», база не меняется.</div><label class="ai-select-all"><input type="checkbox" id="ai-select-all" checked> Выбрать все товары</label><div class="pretty-list ai-plan-list">${plan.items.map((it,i)=>`<label class="pretty-list-card ai-plan-item tone-blue"><input class="ai-item-check" type="checkbox" value="${Number(it.product_id)}" checked><div class="pretty-list-main"><div class="pretty-list-title">${esc(it.name)}</div><div class="pretty-list-meta"><span>${esc(it.model||'')}</span><span>${esc(it.barcode||'')}</span></div><div class="ai-change-list">${it.changes.map(ch=>`<div class="ai-change"><span>${esc(ch.label)}</span><b>${esc(aiValue(ch.field,ch.before))} <i>→</i> ${esc(aiValue(ch.field,ch.after))}</b></div>`).join('')}</div></div><button class="ai-open-product" type="button" data-ai-open="${Number(it.product_id)}" aria-label="Открыть товар">›</button></label>`).join('')}</div><div class="ai-plan-footer"><div id="ai-selected-count">Выбрано ${plan.count} из ${plan.count}</div><div class="ai-plan-actions"><button id="ai-cancel-plan" type="button">Отменить</button><button id="ai-apply-plan" class="primary" type="button">Подтвердить и применить</button></div></div>`;
 const checks=()=>[...box.querySelectorAll('.ai-item-check')]; const updateCount=()=>{const a=checks(),n=a.filter(x=>x.checked).length;$('#ai-selected-count').textContent=`Выбрано ${n} из ${a.length}`;$('#ai-apply-plan').disabled=n===0;$('#ai-select-all').checked=n===a.length;$('#ai-select-all').indeterminate=n>0&&n<a.length};
 $('#ai-select-all').onchange=e=>{checks().forEach(x=>x.checked=e.target.checked);updateCount()};checks().forEach(x=>x.onchange=updateCount);box.querySelectorAll('[data-ai-open]').forEach(b=>b.onclick=e=>{e.preventDefault();openProduct(Number(b.dataset.aiOpen))});
 $('#ai-cancel-plan').onclick=async()=>{try{await api('ai_cancel',{body:{token:plan.token}})}catch(e){}state.aiPlan=null;box.classList.add('hidden');box.innerHTML='';$('#ai-answer').textContent='План отменён. Изменения не применялись.'};
 $('#ai-apply-plan').onclick=async()=>{const ids=checks().filter(x=>x.checked).map(x=>Number(x.value));if(!ids.length)return;if(!confirm(`Применить показанные изменения к ${ids.length} товарам?`))return;const btn=$('#ai-apply-plan');btn.disabled=true;btn.textContent='Применяю…';try{const j=await api('ai_apply',{body:{token:plan.token,product_ids:ids}});state.aiPlan=null;box.classList.add('hidden');box.innerHTML='';$('#ai-answer').innerHTML=`<div class="ai-success"><b>Готово.</b> Изменения применены к ${Number(j.result.applied_count||0)} товарам.</div>`;state.productSearchLoaded=false;state.analyticsData=null;await loadDashboard()}catch(e){toast(e.message);$('#ai-answer').textContent='Ошибка применения: '+e.message;btn.disabled=false;btn.textContent='Подтвердить и применить'}};
}
function renderAiMatches(j){const items=j.items||[];const more=j.truncated?'<div class="list-sub">Показаны первые 200 позиций.</div>':'';$('#ai-answer').innerHTML=`<div class="ai-match-summary"><b>${esc(j.answer||'Найдены товары')}</b><span>${Number(j.count||items.length)} поз.</span></div>${more}<div class="pretty-list ai-match-list">${items.map(it=>`<div class="pretty-list-card clickable tone-blue" data-open-product="${Number(it.product_id)}"><div class="pretty-list-main"><div class="pretty-list-title">${esc(it.name)}</div><div class="pretty-list-meta"><span>${esc(it.model||'')}</span><span>Остаток ${Number(it.quantity||0)}</span><span>${esc(it.stock_status||'')}</span></div></div><div class="pretty-list-side"><b>${money(it.price)}</b><small>себест. ${money(it.cost_price)}</small></div><div class="pretty-arrow">›</div></div>`).join('')}</div>`;bindOpenProducts($('#ai-answer'))}
$('#ai-send').onclick=async()=>{const q=$('#ai-question').value.trim();if(!q)return;$('#ai-answer').textContent='Разбираю запрос…';renderAiPlan(null);$('#ai-send').disabled=true;try{const j=await api('ai_request',{body:{question:q}});if(j.kind==='plan'){ $('#ai-answer').textContent='AI подготовил изменения. Проверьте список ниже.';renderAiPlan(j.plan)}else if(j.kind==='matches'){renderAiMatches(j)}else{$('#ai-answer').textContent=j.answer||'Готово.'}}catch(e){$('#ai-answer').textContent='Ошибка: '+e.message}finally{$('#ai-send').disabled=false}};
function esc(s){const v=decodeLabelText(String(s??''));return v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}

async function openScanner(cb){state.scanCallback=cb;$('#scanner').classList.remove('hidden');$('#scanner-fallback').classList.add('hidden');$('#scanner-status').textContent='Запрашиваю камеру…';try{state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const v=$('#video');v.srcObject=state.stream;await v.play();if('BarcodeDetector'in window){state.detector=new BarcodeDetector({formats:['code_128','qr_code','ean_13','ean_8','upc_a','upc_e']});scanLoop()}else{throw new Error('BarcodeDetector unsupported')}}catch(e){$('#video').classList.add('hidden');$('#scanner-fallback').classList.remove('hidden');$('#scanner-status').textContent='Введите код вручную.'}}
async function scanLoop(){if($('#scanner').classList.contains('hidden')||!state.detector)return;try{const codes=await state.detector.detect($('#video'));if(codes.length){const code=codes[0].rawValue;closeScanner();if(state.scanCallback)state.scanCallback(code);return}}catch(e){}setTimeout(scanLoop,350)}
function closeScanner(){if(state.stream){state.stream.getTracks().forEach(t=>t.stop());state.stream=null}$('#scanner').classList.add('hidden');$('#video').classList.remove('hidden')}
$('#scanner-close').onclick=closeScanner;
$('#scanner-manual-go').onclick=()=>{const c=$('#scanner-manual').value;closeScanner();if(state.scanCallback)state.scanCallback(c)};
$('#scan-head').onclick=()=>{if(isCashier()){go('sale');openScanner(code=>addByCode(code));return}openScanner(async code=>{try{const j=await api('find',{query:{code}});if(j.product)openProduct(j.product.product_id);else toast('Товар не найден')}catch(e){toast(e.message)}})};
$('#cashier-web-scan-nav').onclick=()=>{if(!isCashier())return;go('sale');openScanner(code=>addByCode(code))};
$('#sale-scan').onclick=()=>openScanner(code=>addByCode(code));
$('#receive-scan').onclick=()=>openScanner(code=>{$('#receive-code').value=code;findReceive(code)});
$('#logout-btn').onclick=async()=>{try{await api('logout')}catch(e){}state.cart=[];state.role='admin';document.body.classList.remove('role-cashier');showLogin();$('#password').value='';$('#login-error').textContent=''};

